from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents for amount_cents at rate (a decimal fraction, e.g. 0.0825).

    Rounds with banker's rounding (ROUND_HALF_EVEN), per Finance.
    """
    tax = Decimal(amount_cents) * Decimal(str(rate))
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
